CustomField.formula:
/* DATA SENSITIVITY */ CASE( TEXT(DataSensitivity__c), "Public", 0, "Internal", 2, "Confidential", 4, "Restricted", 8, 0 )
/* CLIENT IMPACT */ + CASE( TEXT(ClientImpact__c), "None", 0, "Indirect", 2, "Direct", 4, "Automated", 6, 0 )
/* BUSINESS CRITICALITY */ + CASE( TEXT(Business_Criticality__c), "Low", 0, "Medium", 1, "High", 2, "Critical", 3, 0 )
/* CONNECTOR EXPOSURE */ + ConnectorExposureScore__c
/* SHARING EXPOSURE */ + MIN( 2, MAX( 0, ( IF(INCLUDES(Team__c, "DBS"), 1, 0) + IF(INCLUDES(Team__c, "DCO"), 1, 0) + IF(INCLUDES(Team__c, "DCR"), 1, 0) + IF(INCLUDES(Team__c, "Digital_Marketing"), 1, 0) + IF(INCLUDES(Team__c, "Direction"), 1, 0) + IF(INCLUDES(Team__c, "Equity"), 1, 0) + IF(INCLUDES(Team__c, "Fixed_Income"), 1, 0) + IF(INCLUDES(Team__c, "Investment Solutions"), 1, 0) + IF(INCLUDES(Team__c, "Marketing"), 1, 0) + IF(INCLUDES(Team__c, "ProductSpecialists"), 1, 0) + IF(INCLUDES(Team__c, "Product Strategy"), 1, 0) + IF(INCLUDES(Team__c, "RFP"), 1, 0) + IF(INCLUDES(Team__c, "Sales"), 1, 0) ) - 1 ) )
